import React, { useState } from 'react';
import './Calendrier.css';
import AjouterTrajet from './AjouterTrajet';

const Calendrier = () => {
  const [activeTab, setActiveTab] = useState('Aujourd\'hui');
  const [showModal, setShowModal] = useState(false);
  const [selectedPerson, setSelectedPerson] = useState('Tous');

  const tabs = ['Aujourd\'hui', 'Personne', 'Semaine'];

  const personnes = ['Tous', 'Loïc', 'Paul', 'Jose', 'Jean', 'Jase'];

  const handleSaveTrajet = (trajetData) => {
    console.log('Trajet enregistré:', trajetData);
    setShowModal(false);
  };

  return (
    <div className="page-content full-width">

      {/* Header fixe */}
      <div className="calendrier-header">
        <div className="tabs-container">
          {tabs.map(tab => (
            <button
              key={tab}
              className={`tab-button ${activeTab === tab ? 'active' : ''}`}
              onClick={() => setActiveTab(tab)}
            >
              {tab}
            </button>
          ))}
        </div>

        {/* Bouton Ajouter un trajet */}
        <div className="add-trajet-container">
          <button
            className="add-trajet-btn"
            onClick={() => setShowModal(true)}
          >
            <span>+</span> Ajouter un trajet
          </button>
        </div>
      </div>

      {/* Contenu selon onglet actif */}
      <div className="tab-content">
        {activeTab === 'Aujourd\'hui' && (
          <div>
            {/* Ici tu peux afficher ton calendrier du jour */}
            <h3>Calendrier du jour</h3>
          </div>
        )}

        {activeTab === 'Personne' && (
          <div>
            <h3>Filtrer par personne</h3>
            <select
              value={selectedPerson}
              onChange={(e) => setSelectedPerson(e.target.value)}
            >
              {personnes.map(p => <option key={p}>{p}</option>)}
            </select>
            <div>
              {/* Affichage filtré des événements pour la personne */}
              <p>Planning affiché pour: {selectedPerson}</p>
            </div>
          </div>
        )}

        {activeTab === 'Semaine' && (
          <div>
            <h3>Planning de la semaine</h3>
            <div className="week-filter">
              <button>Jour</button>
              <button>Semaine</button>
              <button>Mois</button>
              <button>Année</button>
            </div>
            {/* Ici tu peux réutiliser ton composant calendrier semaine */}
          </div>
        )}
      </div>

      {/* Modale Ajouter Trajet */}
      <AjouterTrajet
        isOpen={showModal}
        onClose={() => setShowModal(false)}
        onSave={handleSaveTrajet}
      />

    </div>
  );
};

export default Calendrier;
